// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    ACCURAL_DEPOSIT c;
    function setUp() public { c = new ACCURAL_DEPOSIT(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 100 ether);
        LogProbe freshLog = new LogProbe();
        c.SetLogFile(address(freshLog));
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();
        // General rule: every deposit is recorded by the CURRENT log file,
        // so the freshly set logger must have received exactly one message
        // from actor with value == amount.
        (address sender, string memory data, uint256 val,) = freshLog.History(0);
        assertTrue(
            freshLog.HistoryLength() == 1 && sender == actor && val == amount &&
            keccak256(bytes(data)) == keccak256(bytes("Put"))
        );
    }
}

contract LogProbe {
    struct Message { address Sender; string Data; uint256 Val; uint256 Time; }
    Message[] public History;
    function HistoryLength() external view returns (uint256) { return History.length; }
    function AddMessage(address _adr, uint256 _val, string memory _data) external {
        History.push(Message(_adr, _data, _val, block.timestamp));
    }
    receive() external payable {}
}
